#!/usr/bin/env python3
"""Discard Hold'em bot.

Every street it builds, with numpy, the value of all 1326 two-card hands over
sampled or enumerated runouts. From that it gets:
  * a strength for every possible opponent hand,
  * a weighted opponent range, narrowed by each action and by the revealed
    discard,
  * the bot's equity against each hand in that range.
Decisions are one-step expected-value comparisons. Fold, call and raise
frequencies come from counters on this opponent, seeded with priors.
Only stdlib and numpy. No files, no network.
"""
import base64
import json
import math
import random
import sys
import time
import zlib

import numpy as np

RANKS = "23456789TJQKA"
SUITS = "shdc"
FOLD, PASS, RS, RM, RB, RJ = range(6)  # opponent action classes: PASS = check or call
STREET = {"preflop": 0, "flop": 1, "turn": 2, "river": 3}
PRE_BUCKETS = 16
USE_LOCK = True

# Precomputed table, zlib+base64 of uint16 [class strength, then class x bucket equity].
PRE_DATA = ""


def cid(card):
    return RANKS.index(card[0]) * 4 + SUITS.index(card[1])


# ---------------------------------------------------------------- evaluator

def top_ranks(ranks, n):
    v = 0
    for r in ranks[:n]:
        v = v * 16 + r
    return v * 16 ** (5 - n)


def straight_high(mask):
    """Top rank of the best straight in a 13-bit rank mask, or -1."""
    m = (mask << 1) | (mask >> 12 & 1)  # bit 0 = ace low
    for hi in range(13, 3, -1):
        if (m >> (hi - 4)) & 31 == 31:
            return hi - 1
    return -1


def nonflush_value(counts):
    desc = [r for r in range(12, -1, -1) if counts[r]]
    mask = sum(1 << r for r in desc)
    four = [r for r in desc if counts[r] == 4]
    trips = [r for r in desc if counts[r] == 3]
    pairs = [r for r in desc if counts[r] == 2]
    if four:
        q = four[0]
        return (7 << 20) + top_ranks([q] + [r for r in desc if r != q], 2)
    if trips and (len(trips) > 1 or pairs):
        t = trips[0]
        p = max(trips[1:] + pairs)
        return (6 << 20) + top_ranks([t, p], 2)
    sh = straight_high(mask)
    if sh >= 0:
        return (4 << 20) + top_ranks([sh], 1)
    if trips:
        t = trips[0]
        return (3 << 20) + top_ranks([t] + [r for r in desc if r != t], 3)
    if len(pairs) >= 2:
        a, b = pairs[:2]
        return (2 << 20) + top_ranks([a, b] + [r for r in desc if r != a and r != b], 3)
    if pairs:
        p = pairs[0]
        return (1 << 20) + top_ranks([p] + [r for r in desc if r != p], 4)
    return top_ranks(desc, 5)


def build_nonflush():
    """All rank multisets of seven cards, keyed by a base-5 sum of ranks."""
    keys, vals = [], []
    counts = [0] * 13

    def rec(rank, left):
        if rank == 12:
            if left <= 4:
                counts[12] = left
                keys.append(sum(c * 5 ** i for i, c in enumerate(counts)))
                vals.append(nonflush_value(counts))
                counts[12] = 0
            return
        for c in range(min(4, left) + 1):
            counts[rank] = c
            rec(rank + 1, left - c)
        counts[rank] = 0

    rec(0, 7)
    keys = np.array(keys, dtype=np.int64)
    order = np.argsort(keys)
    return keys[order], np.array(vals, dtype=np.int32)[order]


def build_flush():
    fl = np.zeros(8192, dtype=np.int32)
    for mask in range(8192):
        desc = [r for r in range(12, -1, -1) if mask >> r & 1]
        if len(desc) < 5:
            continue
        sh = straight_high(mask)
        fl[mask] = (8 << 20) + top_ranks([sh], 1) if sh >= 0 else (5 << 20) + top_ranks(desc, 5)
    return fl


SKEYS, SVALS = build_nonflush()
FL = build_flush()
POW5 = 5 ** np.arange(13, dtype=np.int64)

# ---------------------------------------------------------------- pair and triple tables

PAIRS = np.array([(a, b) for a in range(52) for b in range(a + 1, 52)], dtype=np.int64)
NP = len(PAIRS)
PIDX = np.full((52, 52), -1, dtype=np.int64)
PIDX[PAIRS[:, 0], PAIRS[:, 1]] = np.arange(NP)
PIDX[PAIRS[:, 1], PAIRS[:, 0]] = np.arange(NP)
PMASK = (1 << PAIRS[:, 0]) | (1 << PAIRS[:, 1])
_pr = np.sort(PAIRS >> 2, axis=1)
_prk = _pr[:, 0] * 13 + _pr[:, 1]
_u, PRP = np.unique(_prk, return_inverse=True)
RPKEY = POW5[_u // 13] + POW5[_u % 13]  # one key per unordered rank pair (91)
PBITS = np.zeros((4, NP), dtype=np.int64)
for _s in range(4):
    for _c in (0, 1):
        _m = (PAIRS[:, _c] & 3) == _s
        PBITS[_s][_m] |= 1 << (PAIRS[:, _c][_m] >> 2)

TRIPS = np.array([(a, b, c) for a in range(52) for b in range(a + 1, 52) for c in range(b + 1, 52)],
                 dtype=np.int64)
NT = len(TRIPS)
TMASK = (1 << TRIPS[:, 0]) | (1 << TRIPS[:, 1]) | (1 << TRIPS[:, 2])
# The three ways to keep two cards from a triple, and the card discarded in each.
PT = np.stack([PIDX[TRIPS[:, 0], TRIPS[:, 1]], PIDX[TRIPS[:, 0], TRIPS[:, 2]],
               PIDX[TRIPS[:, 1], TRIPS[:, 2]]], axis=1)
TDISC = TRIPS[:, ::-1]
_tr = TDISC >> 2
LOWKEEP = (_tr == _tr.min(1, keepdims=True)).astype(np.float64)
LOWKEEP /= LOWKEEP.sum(1, keepdims=True)  # opponent that always drops its lowest rank


def triple_id(*cards):
    a, b, c = sorted(cards)
    return int(np.searchsorted(TKEY, a * 2704 + b * 52 + c))


TKEY = TRIPS[:, 0] * 2704 + TRIPS[:, 1] * 52 + TRIPS[:, 2]


def build_classes():
    """Suit-isomorphism class of each of the 22100 triples (1755 classes)."""
    order = np.argsort(-(TRIPS >> 2), axis=1, kind="stable")
    c = np.take_along_axis(TRIPS, order, axis=1)
    r, s = c >> 2, c & 3
    e12, e13, e23 = s[:, 0] == s[:, 1], s[:, 0] == s[:, 2], s[:, 1] == s[:, 2]
    pat = e12 * 4 + e13 * 2 + e23 * 1
    pair_hi, pair_lo = r[:, 0] == r[:, 1], r[:, 1] == r[:, 2]
    pat = np.where(pair_hi, (e13 | e23) * 1, pat)
    pat = np.where(pair_lo, (e12 | e13) * 1, pat)
    pat = np.where(pair_hi & pair_lo, 0, pat)
    key = ((r[:, 0] * 13 + r[:, 1]) * 13 + r[:, 2]) * 8 + pat
    return np.unique(key, return_inverse=True)[1]


CLS = build_classes()
NCLS = int(CLS.max()) + 1
if PRE_DATA:
    _d = np.frombuffer(zlib.decompress(base64.b64decode(PRE_DATA)), dtype=np.uint16)
    CSTR = _d[:NCLS] / 65535.0  # percentile of each class among random triples
    PEQ = (_d[NCLS:] / 65535.0).reshape(NCLS, PRE_BUCKETS)  # equity vs each opponent bucket
else:  # only while dev/gen_pre.py is generating the table
    CSTR = np.linspace(0, 1, NCLS)
    PEQ = np.full((NCLS, PRE_BUCKETS), 0.5)
TSTR = CSTR[CLS]
TBUCKET = np.minimum((TSTR * PRE_BUCKETS).astype(np.int64), PRE_BUCKETS - 1)
TORDER = np.argsort(TSTR)


def eval_boards(B):
    """Hand value of all 1326 pairs on each five-card board. B has shape (n, 5)."""
    r, s = B >> 2, B & 3
    key = POW5[r].sum(1)
    idx = np.searchsorted(SKEYS, key[:, None] + RPKEY)
    idx[idx >= len(SKEYS)] = len(SKEYS) - 1  # five of a rank: impossible pairs, masked later
    V = SVALS[idx][:, PRP]
    for su in range(4):
        m = s == su
        sel = np.nonzero(m.sum(1) >= 3)[0]
        if sel.size:
            bits = ((1 << r[sel]) * m[sel]).sum(1)
            V[sel] = np.maximum(V[sel], FL[bits[:, None] | PBITS[su]])
    return V


def board_ok(B):
    """Mask of pairs that do not share a card with each board."""
    bm = (1 << B).sum(1)
    return (PMASK[None, :] & bm[:, None]) == 0


def percentile_rows(V, ok):
    """Mean of rank-among-possible-pairs per row, ties at their midpoint."""
    n = V.shape[0]
    A = V.astype(np.int64)
    A[~ok] = -1
    A += (np.arange(n, dtype=np.int64)[:, None] + 1) << 32
    flat = np.sort(A, axis=1).ravel()
    q = A.ravel()
    mid = (np.searchsorted(flat, q, "left") + np.searchsorted(flat, q, "right")) * 0.5
    nok = ok.sum(1, keepdims=True)
    pct = (mid.reshape(A.shape) - (np.arange(n)[:, None] * NP + (NP - nok))) / np.maximum(nok, 1)
    return (pct * ok).sum(0) / np.maximum(ok.sum(0), 1)


def pair_equity(V, ok, k):
    """Equity of pair k against every pair, averaged over boards where that pair is possible."""
    v = V[:, k, None]
    score = (v > V) + 0.5 * (v == V)
    return (score * ok).sum(0) / np.maximum(ok.sum(0), 1)


# ---------------------------------------------------------------- opponent model

def sz_bucket(ratio):
    return 0 if ratio <= 0.6 else 1 if ratio <= 1.2 else 2 if ratio <= 3.0 else 3


def prior(stc, lvl, sz):
    """Prior [fold, pass, raise small/medium/big/jam]; stc is 0 preflop, 1 postflop."""
    if stc:
        if lvl == 0:
            return [0, .62, .16, .15, .06, .01]
        if sz == 3:
            return [.7, .29, 0, 0, 0, .01]
        if lvl == 1:
            return ([.27, .56, .10, .04, .02, .01], [.38, .50, .06, .03, .02, .01],
                    [.50, .42, .03, .02, .02, .01])[sz]
        if lvl == 2:
            return ([.30, .50, .08, .06, .03, .03], [.40, .45, .04, .05, .03, .03],
                    [.50, .40, .02, .03, .02, .03])[sz]
        return [.45, .45, 0, .02, .03, .05]
    if lvl == 0:
        return [.12, .33, .15, .30, .08, .02]
    if sz == 3:
        return [.8, .2, 0, 0, 0, 0]
    if lvl == 1:
        return ([.20, .62, .05, .08, .03, .02], [.30, .52, .03, .09, .04, .02],
                [.45, .42, .02, .06, .03, .02])[sz]
    if lvl == 2:
        return ([.30, .52, .02, .05, .06, .05], [.30, .52, .02, .05, .06, .05],
                [.40, .45, .02, .03, .05, .05])[sz]
    return [.40, .55, 0, 0, .02, .03]


class Opp:
    """Action counters at three levels of detail, backed off onto the prior."""
    K_POOL, K_SPEC = 6.0, 4.0

    def __init__(self):
        self.counts = {}
        self.cache = {}
        # Rate at which shown hands contradict the action they took, by street.
        self.agg_n, self.agg_off = [0.0] * 4, [0.0] * 4
        self.pas_n, self.pas_off = [0.0] * 4, [0.0] * 4
        self.disc_ll = np.array([0.0, -1.0, -1.0])  # smart, drop lowest, random

    def _dist(self, st, lvl, sz):
        lvl = min(lvl, 3)
        stc = 1 if st else 0
        pool = self.counts.get((stc, lvl, sz))
        p = np.array(prior(stc, lvl, sz), dtype=np.float64)
        if pool is not None:
            p = (pool + self.K_POOL * p) / (pool.sum() + self.K_POOL)
        spec = self.counts.get((10 + st, lvl, sz))
        if spec is not None:
            p = (spec + self.K_SPEC * p) / (spec.sum() + self.K_SPEC)
        return p

    def dist(self, st, lvl, sz):
        key = (st, min(lvl, 3), sz)
        p = self.cache.get(key)
        if p is None:
            p = self.cache[key] = self._dist(st, lvl, sz)
        return p

    def add(self, st, lvl, sz, action):
        lvl = min(lvl, 3)
        for key in ((1 if st else 0, lvl, sz), (10 + st, lvl, sz)):
            c = self.counts.get(key)
            if c is None:
                c = self.counts[key] = np.zeros(6)
            c[action] += 1
        self.cache.clear()

    def eps_agg(self, st):
        return max(.05, (self.agg_off[st] + .15 * 8) / (self.agg_n[st] + 8))

    def eps_pas(self, st):
        return max(.05, (self.pas_off[st] + .12 * 8) / (self.pas_n[st] + 8))

    def disc_pi(self):
        ll = self.disc_ll - self.disc_ll.max()
        p = np.exp(ll)
        return p / p.sum()


def sig(x, thr, tau=0.08):
    return 1.0 / (1.0 + np.exp(np.clip((thr - x) / tau, -30, 30)))


# ---------------------------------------------------------------- hand state

class Hand:
    def __init__(self, msg):
        self.id = msg["hand_id"]
        self.button = msg["seat"] == "button"
        self.hole = [cid(c) for c in msg["hole_cards"]]
        self.table_st = 0  # street whose strength tables are built
        self.board = []
        self.st = 0
        self.bets = [1, 2] if self.button else [2, 1]  # [me, opp] on this street
        self.commit = list(self.bets)
        self.raises = 0  # voluntary raises on this street
        self.sz = 0
        self.seen = 0
        self.last_mine = None
        self.events = []
        self.dead = sum(1 << c for c in self.hole)
        self.W3 = np.where(TMASK & self.dead, 0.0, 1.0)  # weights on opponent triples
        self.w = None  # weights on opponent pairs, after the discard
        self.w_dirty = True
        self.keeps = [PIDX[a, b] for a, b in ((self.hole[0], self.hole[1]), (self.hole[0], self.hole[2]),
                                              (self.hole[1], self.hole[2]))]
        self.E = None  # hero equity per pair, shape (keeps, 1326)
        self.S = None  # strength of each pair on the current street
        self.flop_S = None
        self.opp_disc = None
        self.my_pair = None
        self.Pk = None

    def pot(self):
        return self.commit[0] + self.commit[1]

    def new_street(self, st):
        self.st = st
        self.bets = [0, 0]
        self.raises = 0
        self.sz = 0

    def apply(self, who, action, amount=None):
        other = 1 - who
        if action == "call":
            d = self.bets[other] - self.bets[who]
            self.bets[who] += d
            self.commit[who] += d
        elif action == "raise":
            faced = self.bets[other]
            ratio = (amount - faced) / max(1.0, self.pot() + faced - self.bets[who])
            self.sz = sz_bucket(ratio)
            self.raises += 1
            self.commit[who] += amount - self.bets[who]
            self.bets[who] = amount


# ---------------------------------------------------------------- bot

class Bot:
    def __init__(self):
        self.total = 400
        self.bank = 60000
        self.net = 0
        self.sq = 0.0  # sum of squared hand results, for the match variance
        self.opp = Opp()
        self.h = None
        self.ms_runout = 0.15
        self.rng = np.random.default_rng()
        self.time_left = 60000

    # -- clock -------------------------------------------------------------

    def runouts(self):
        """Runouts for this street, sized to spend about 40% of a fair share of the bank."""
        left = max(1, self.total - self.h.id + 1)
        per_hand = self.time_left / left
        return int(np.clip(0.4 * per_hand / self.ms_runout, 12, 240))

    # -- street tables -----------------------------------------------------

    def enter_street(self, st, board):
        h = self.h
        h.new_street(st)
        h.board = board
        ids = [cid(c) for c in board]
        h.dead |= sum(1 << c for c in ids)
        if st == 1:
            self.flop_tables(ids)
        elif st >= 2:
            self.later_tables(ids)

    def ensure_flop(self, board):
        h = self.h
        if h.E is None:
            h.board = board
            ids = [cid(c) for c in board]
            h.dead |= sum(1 << c for c in ids)
            self.flop_tables(ids)

    def flop_tables(self, ids):
        h = self.h
        t0 = time.perf_counter()
        h.table_st = 1
        h.W3[(TMASK & h.dead) != 0] = 0.0
        rest = np.array([c for c in range(52) if not h.dead >> c & 1])
        n = self.runouts()
        total = len(rest) * (len(rest) - 1) // 2
        picks = self.rng.choice(total, size=min(n, total), replace=False)
        # Unrank a pair index into two different cards.
        i, j = np.triu_indices(len(rest), 1)
        B = np.column_stack([np.tile(ids, (len(picks), 1)), rest[i[picks]], rest[j[picks]]])
        V = eval_boards(B)
        ok = board_ok(B)
        h.S = h.flop_S = percentile_rows(V, ok)
        h.T_order = np.argsort(h.S[PT].max(1))
        h.E = np.array([pair_equity(V, ok, k) for k in h.keeps])
        h.w_dirty = True
        h.Pk = self.keep_probs(h.S)
        dt = (time.perf_counter() - t0) * 1000.0
        self.ms_runout = 0.8 * self.ms_runout + 0.2 * dt / len(picks)

    def keep_probs(self, S):
        """P(opponent keeps each of three pairs) for every triple."""
        s = S[PT] * 40.0
        s -= s.max(1, keepdims=True)
        smart = np.exp(s)
        smart /= smart.sum(1, keepdims=True)
        pi = self.opp.disc_pi()
        return pi[0] * smart + pi[1] * LOWKEEP + pi[2] / 3.0

    def later_tables(self, ids):
        h = self.h
        h.table_st = h.st
        if h.st == 2:
            rest = np.array([c for c in range(52) if not h.dead >> c & 1])
            n = self.runouts()
            if n < len(rest):
                rest = self.rng.choice(rest, size=n, replace=False)
            B = np.column_stack([np.tile(ids, (len(rest), 1)), rest])
        else:
            B = np.array([ids])
        V = eval_boards(B)
        ok = board_ok(B)
        h.S = percentile_rows(V, ok)
        h.E = pair_equity(V, ok, h.my_pair)[None, :]
        pm = (PMASK & h.dead) != 0
        if h.w is None:  # no discard seen: should not happen, stay safe
            h.w = np.ones(NP)
        h.w[pm] = 0.0

    def pair_weights(self):
        """Opponent pair weights for the current street."""
        h = self.h
        if h.st <= 1 and h.w_dirty:
            w = np.bincount(PT.ravel(), (h.W3[:, None] * h.Pk).ravel(), NP)
            w[(PMASK & h.dead) != 0] = 0.0
            h.w, h.w_dirty = w, False
        return h.w

    def on_discard_result(self, msg):
        h = self.h
        if h is None:
            return
        mine, d = cid(msg["my_discard"]), cid(msg["opp_discard"])
        h.opp_disc = d
        keep = [c for c in h.hole if c != mine]
        h.my_pair = PIDX[keep[0], keep[1]]
        sel = np.nonzero(TMASK & (1 << d))[0]
        col = np.argmax(TDISC[sel] == d, axis=1)
        pairs = PT[sel, col]
        w = np.bincount(pairs, h.W3[sel] * h.Pk[sel, col], NP)
        h.dead |= (1 << mine) | (1 << d)
        w[(PMASK & h.dead) != 0] = 0.0
        if w.sum() <= 0:
            w = ((PMASK & h.dead) == 0).astype(np.float64)
        h.w = w
        h.w_dirty = False

    # -- reading the opponent ----------------------------------------------

    def percentiles(self, weights, order):
        cdf = np.cumsum(weights[order])
        x = np.empty(len(weights))
        x[order] = cdf / max(cdf[-1], 1e-12)
        return x

    def opp_action(self, entry):
        h = self.h
        st = STREET[entry["street"]]
        action = entry["action"]
        lvl, sz = h.raises, h.sz
        p = self.opp.dist(st, lvl, sz)
        if action == "raise":
            faced = h.bets[0]
            ratio = (entry["amount"] - faced) / max(1.0, h.pot() + faced - h.bets[1])
            a = RS + sz_bucket(ratio)
        else:
            a = FOLD if action == "fold" else PASS
        self.opp.add(st, lvl, sz, a)
        if action != "fold" and st == h.table_st:
            self.narrow(st, a, p)
        h.apply(1, action, entry.get("amount"))

    def narrow(self, st, a, p):
        """Bayes update of the range. Each action is taken as its slice of the strength order."""
        h = self.h
        if st == 0:
            weights, order = h.W3, TORDER
        elif st == 1:
            weights, order = h.W3, h.T_order
        else:
            weights, order = h.w, np.argsort(h.S)
        x = self.percentiles(weights, order)
        thr_r = 1.0 - p[RS:].sum()
        if a >= RS:
            thr = 1.0 - p[a:].sum()
            e = self.opp.eps_agg(st)
            L = e + (1 - e) * sig(x, thr)
            h.events.append((st, 0, thr, x))
        elif h.bets[1] < h.bets[0]:  # a call
            e = self.opp.eps_pas(st)
            L = e + (1 - e) * sig(x, p[FOLD]) * (1 - 0.7 * sig(x, thr_r))
            h.events.append((st, 1, thr_r, x))
        else:  # a check
            e = self.opp.eps_pas(st)
            L = e + (1 - e) * (1 - sig(x, thr_r))
            h.events.append((st, 1, thr_r, x))
        weights *= L
        h.w_dirty = True

    def ingest(self, history, board=None):
        h = self.h
        for entry in history[h.seen:]:
            st = STREET[entry["street"]]
            if st > h.st and board is not None:
                self.enter_street(st, board[:(st + 2)])
            elif st > h.st:
                h.new_street(st)
            if entry["actor"] == "opp":
                self.opp_action(entry)
            else:  # only reached if the engine corrected us or a reply was lost
                h.apply(0, entry["action"], entry.get("amount"))
        h.seen = max(h.seen, len(history))

    def learn_showdown(self, msg):
        h = self.h
        if h.opp_disc is None or not msg.get("opp_hole_cards"):
            return
        a, b = (cid(c) for c in msg["opp_hole_cards"])
        d = h.opp_disc
        pair = PIDX[a, b]
        tid = triple_id(a, b, d)
        o = self.opp
        for st, kind, thr, x in h.events:
            v = x[tid] if len(x) == NT else x[pair]
            if kind == 0:
                o.agg_n[st] += 1
                o.agg_off[st] += v < thr - 0.1
            else:
                o.pas_n[st] += 1
                o.pas_off[st] += v > thr + 0.1
        if h.flop_S is not None:
            s = h.flop_S[PT[tid]] * 40.0
            s -= s.max()
            smart = np.exp(s)
            smart /= smart.sum()
            col = int(np.argmax(TDISC[tid] == d))
            like = np.array([smart[col], LOWKEEP[tid, col], 1 / 3])
            o.disc_ll = o.disc_ll + np.log(np.maximum(like, 0.02))

    # -- decision ----------------------------------------------------------

    def value(self, eq, pot, behind, st, ip):
        """Chips a hand expects to take from a pot, counting streets still to play.

        Strong hands win more than the pot as stacks go in; weak ones lose a little
        beyond their share, less so because they can still fold.
        """
        left = 3 - st
        if left == 0 or behind <= 0:
            return eq * pot
        q = eq + left * (0.012 if ip else -0.012)
        grow = min(behind, pot * left * 0.75)
        return q * pot + (2 * q - 1) * grow * (0.35 if q > 0.5 else 0.14)

    def range_view(self):
        """Opponent range sorted strongest first, as cumulative weight and weighted equity."""
        h = self.h
        if h.st == 0:
            cls = CLS[triple_id(*h.hole)]
            w = np.bincount(TBUCKET, h.W3, PRE_BUCKETS)[::-1]
            e = PEQ[cls][::-1]
        else:
            pw = self.pair_weights()
            if pw.sum() <= 0:
                pw = ((PMASK & h.dead) == 0).astype(np.float64)
                h.w = pw
            if h.st == 1:
                eqs = h.E @ pw / pw.sum()
                best = int(np.argmax(eqs))
                e = h.E[best]
            else:
                e = h.E[0]
            order = np.argsort(-h.S)
            w, e = pw[order], e[order]
        cw = np.cumsum(w)
        cwe = np.cumsum(w * e)
        return cw, cwe

    def decide(self, req):
        h = self.h
        st = STREET[req["street"]]
        legal = req["legal_actions"]
        P, tc = req["pot"], req["to_call"]
        ip = h.button  # the button acts last on every street after the flop is dealt
        cw, cwe = self.range_view()
        tot = cw[-1]
        o = self.opp

        def window(lo, hi):
            i = int(np.searchsorted(cw, min(hi, 1.0) * tot))
            i = min(i, len(cw) - 1)
            if lo <= 0:
                return float(cwe[i] / max(cw[i], 1e-12))
            j = min(int(np.searchsorted(cw, lo * tot)), len(cw) - 1)
            if cw[i] - cw[j] < 1e-9:
                return float(cwe[i] / max(cw[i], 1e-12))
            return float((cwe[i] - cwe[j]) / (cw[i] - cw[j]))

        eq = float(cwe[-1] / max(tot, 1e-12))
        behind = min(req["my_stack"], req["opp_stack"])
        options = []  # (ev, action, amount)

        if "fold" in legal:
            options.append((0.0, "fold", None))
        if "check" in legal:
            options.append((self.ev_check(st, ip, P, behind, eq, window), "check", None))
        if "call" in legal:
            ev = self.value(eq, P + tc, behind - tc, st, ip) - tc
            if st == 0 and h.button and h.raises == 0:  # a limp lets the big blind raise
                r = o.dist(0, 0, 0)[RS:].sum()
                ev = (1 - r) * ev + r * -tc
            options.append((ev, "call", None))
        if "raise" in legal:
            for to in self.sizes(req, eq):
                options.append((self.ev_raise(st, ip, req, to, window), "raise", to))
        if "fold" in legal and "call" in legal and tc >= req["my_stack"] and tc >= 20:
            options = self.match_call(options, eq, req)
        return self.pick(options, P, req)

    def win_prob(self, net):
        """Chance of ending the match ahead from `net` after this hand: the remaining hands
        add a shrunk estimate of our edge per hand, with this match's spread."""
        h = self.h
        left = self.total - h.id
        if left <= 0:
            return 1.0 if net > 0 else 0.5 if net == 0 else 0.0
        mean = self.net / (h.id + 40.0)
        sd = max(10.0, (self.sq / max(1, h.id)) ** 0.5) * left ** 0.5
        return 0.5 * (1.0 + math.erf((net + mean * left) / (sd * 2 ** 0.5)))

    def match_call(self, options, eq, req):
        """An all-in call settles the hand, so score it by the match it leaves: a favourite
        passes on coin flips, an underdog takes them. Chips decide when both score alike."""
        spent = 200 - req["my_stack"]
        stake = spent + req["to_call"]  # stacks start equal, so a won all-in pays what it risks
        fold = self.win_prob(self.net - spent)
        call = eq * self.win_prob(self.net + stake) + (1 - eq) * self.win_prob(self.net - stake)
        if abs(call - fold) < 0.002:
            return options
        keep = "call" if call > fold else "fold"
        return [o for o in options if o[1] == keep or o[1] not in ("call", "fold")]

    def ev_check(self, st, ip, P, behind, eq, window):
        h = self.h
        if ip:
            return self.value(eq, P, behind, st, True)
        p = self.opp.dist(st, h.raises, h.sz)
        b = float(p[RS:].sum())
        B = min(0.7 * P, behind)
        lo = window(b, 1.0)
        hi = window(0, b) if b > 0 else eq
        facing = max(0.0, self.value(hi, P + 2 * B, behind - B, st, False) - B)
        return (1 - b) * self.value(lo, P, behind, st, False) + b * facing

    def ev_raise(self, st, ip, req, to, window):
        h = self.h
        P = req["pot"]
        my_bet, opp_bet = req["my_bet"], req["opp_bet"]
        add = to - my_bet
        faced = to - opp_bet
        ratio = faced / max(1.0, P + req["to_call"])
        p = self.opp.dist(st, h.raises + 1, sz_bucket(ratio))
        f, c, r = float(p[FOLD]), float(p[PASS]), float(p[RS:].sum())
        allin = to >= req["max_raise"]
        if allin or req["raises_left"] <= 1:
            c, r = c + r, 0.0
        pot_call = P + add + faced
        behind = max(0, min(req["my_stack"] - add, req["opp_stack"] - faced))
        ev = f * P + c * (self.value(window(r, 1 - f), pot_call, behind, st, ip) - add)
        if r > 0:
            to2 = min(req["max_raise"], to + max(2.5 * faced, 4))
            extra = to2 - to
            q = self.value(window(0, r), pot_call + 2 * extra, behind - extra, st, ip)
            ev += r * max(-add, q - add - extra)
        return ev

    def sizes(self, req, eq):
        st = STREET[req["street"]]
        lo, hi = req["min_raise"], req["max_raise"]
        P = req["pot"] + req["to_call"]
        b = req["opp_bet"]
        if st == 0 and b <= 2:
            raw = [5, 6, 8]
        elif st == 0:
            raw = [2.5 * b, 3.5 * b]
        else:
            raw = [b + f * P for f in (0.33, 0.66, 1.0, 1.5)]
        # A shove far above the pot needs a real hand: fold-rate estimates there are thin,
        # and the callers it meets are the ones that beat a medium hand.
        out = {hi} if hi - b <= 3 * P or eq >= 0.68 else set()
        for x in raw:
            x = int(max(lo, min(hi, round(x))))
            # A bet that leaves under a third of the pot behind may as well be all-in.
            if hi - x < 0.3 * (P + 2 * (x - b)):
                x = hi
            out.add(x)
        return sorted(out) or [lo]

    def lock_budget(self):
        """Chips this hand may risk once folding out the match still wins it; None = no limit.

        The win is locked only if it is in doubt, or the chip cap leaves nothing more to earn.
        """
        h = self.h
        left = self.total - h.id
        cost = left // 2 * 3 + (left % 2) * (2 if h.button else 1)
        budget = self.net - cost - 1
        if not USE_LOCK or budget < 0 or budget >= 200:
            return None
        mean = self.net / max(1, h.id)
        sd = max(20.0, (self.sq / max(1, h.id)) ** 0.5)
        safe = (self.net + max(0.0, mean) * left) / (sd * max(1, left) ** 0.5)
        cap = 400 if self.total <= 400 else 1000  # Rulebook 8.3 tie-break cap (provisional)
        return budget if safe < 2.0 or budget > cap else None

    def pick(self, options, P, req):
        h = self.h
        budget = self.lock_budget()
        if budget is not None:
            safe = []
            for ev, act, amt in options:
                add = req["to_call"] if act == "call" else amt - req["my_bet"] if act == "raise" else 0
                if act in ("fold", "check") or h.commit[0] + add <= budget:
                    safe.append((ev, act, amt))
            options = safe
        temp = max(0.25, 0.012 * P)
        evs = np.array([o[0] for o in options])
        probs = np.exp(np.clip((evs - evs.max()) / temp, -40, 0))
        probs[evs < evs.max() - 3 * temp] = 0.0
        choice = options[int(self.rng.choice(len(options), p=probs / probs.sum()))]
        _, act, amt = choice
        if act == "raise":
            return {"type": "action", "action": "raise", "amount": int(amt)}
        return {"type": "action", "action": act}

    # -- protocol handlers -------------------------------------------------

    def on_action(self, req):
        h = self.h
        self.time_left = req.get("time_left_ms", self.time_left)
        if self.time_left < 1000:
            return panic_action(req)
        st = STREET[req["street"]]
        board = req["board"]
        self.ingest(req["history"], board)
        if st > h.st:
            self.enter_street(st, board)
        reply = self.decide(req)
        h.apply(0, reply["action"], reply.get("amount"))
        h.seen += 1
        h.last_mine = reply["action"]
        return reply

    def on_discard(self, req):
        h = self.h
        self.time_left = req.get("time_left_ms", self.time_left)
        hole = req["hole_cards"]
        if self.time_left < 1000:
            return {"type": "discard", "card": min(hole, key=lambda c: RANKS.index(c[0]))}
        # The opponent's closing action is not in any message yet, so infer it.
        if h.last_mine == "raise":
            self.opp_action({"street": ("preflop", "flop")[h.st], "actor": "opp", "action": "call",
                             "amount": h.bets[0]})
            h.seen += 1
        elif h.last_mine == "check" and h.st == 1 and not h.button:
            self.opp_action({"street": "flop", "actor": "opp", "action": "check"})
            h.seen += 1
        self.ensure_flop(req["board"])
        pw = self.pair_weights()
        eqs = h.E @ pw / max(pw.sum(), 1e-12)
        best = eqs.max()
        close = np.nonzero(eqs >= best - 0.004)[0]
        keep = int(self.rng.choice(close))
        return {"type": "discard", "card": hole[2 - keep]}  # keeps[i] drops hole[2 - i]

    def on_result(self, msg):
        h = self.h
        self.net += msg.get("net", 0)
        self.sq += msg.get("net", 0) ** 2
        if h is None:
            return
        self.ingest(msg.get("history", []))
        if msg.get("result") == "showdown":
            self.learn_showdown(msg)
        self.h = None


def panic_action(req):
    legal = req.get("legal_actions", [])
    if "check" in legal:
        return {"type": "action", "action": "check"}
    if "call" in legal and req.get("to_call", 99) <= 2:
        return {"type": "action", "action": "call"}
    return {"type": "action", "action": "fold"}


def main():
    bot = Bot()
    for line in sys.stdin:
        line = line.strip()
        if not line:
            continue
        try:
            msg = json.loads(line)
        except ValueError:
            continue
        t = msg.get("type")
        reply = None
        try:
            if t == "init":
                bot.total = msg.get("total_hands", bot.total)
                bot.time_left = msg.get("time_bank_ms", bot.time_left)
            elif t == "new_hand":
                bot.h = Hand(msg)
            elif t == "action_request":
                reply = bot.on_action(msg)
            elif t == "discard_request":
                reply = bot.on_discard(msg)
            elif t == "discard_result":
                bot.on_discard_result(msg)
            elif t == "hand_result":
                bot.on_result(msg)
            elif t == "match_end":
                break
        except Exception as exc:  # a forfeit costs far more than one bad decision
            print("error:", repr(exc), file=sys.stderr)
            if t == "action_request":
                reply = panic_action(msg)
            elif t == "discard_request":
                reply = {"type": "discard", "card": msg["hole_cards"][0]}
        if reply is not None:
            sys.stdout.write(json.dumps(reply) + "\n")
            sys.stdout.flush()


if __name__ == "__main__":
    main()
